# Generated by manage.py generate_test_cases.
"""Exercise call lifecycle, unique media identities and retention."""

from functools import partial
from typing import Any

from django.core.exceptions import ValidationError

from bloomerp.models.communication.conferencing import ConferenceSession
from bloomerp.tests.base import (
    BloomerpModelTestCase,
    ExpectedModelException,
    ModelScenario,
)

from .fixtures import ConferenceFixtures


class TestConferenceSessionModel(ConferenceFixtures, BloomerpModelTestCase):
    model = ConferenceSession

    def get_test_scenarios(self) -> list[ModelScenario[ConferenceSession]]:
        """Cover valid lifecycle transitions and immutable session boundaries."""
        return [
            ModelScenario(
                name="New sessions have distinct provider rooms",
                preparation=self.prepare,
                create_args=self.session_args,
                create_validators=self.distinct_room_name,
                update_args=self.active_args,
            ),
            ModelScenario(
                name="Only one open call per room",
                preparation=self.prepare,
                create_args=self.duplicate_args,
                expected_exceptions=[ExpectedModelException("create", ValidationError)],
            ),
            ModelScenario(
                name="Archived rooms cannot start calls",
                preparation=self.prepare,
                create_args=self.archived_args,
                expected_exceptions=[ExpectedModelException("create", ValidationError)],
            ),
            ModelScenario(
                name="Completed calls never reopen",
                preparation=self.prepare,
                create_args=self.ended_args,
                update_args=self.active_args,
                expected_exceptions=[ExpectedModelException("update", ValidationError)],
            ),
            ModelScenario(
                name="A new call follows a completed call",
                preparation=self.prepare,
                create_args=self.ended_args,
                post_create=self.add_later_session,
            ),
            ModelScenario(
                name="Provider name cannot change",
                preparation=self.prepare,
                create_args=self.session_args,
                update_args={"livekit_room_name": "replacement"},
                expected_exceptions=[ExpectedModelException("update", ValidationError)],
            ),
            ModelScenario(
                name="Active calls require start time",
                preparation=self.prepare,
                create_args=partial(self.session_args, status="active"),
                expected_exceptions=[ExpectedModelException("create", ValidationError)],
            ),
        ]

    def distinct_room_name(self, session: ConferenceSession) -> bool:
        """Ensure tokens for a different call cannot target the new provider room."""
        return session.livekit_room_name != self.session.livekit_room_name

    def active_args(self) -> dict[str, Any]:
        """Describe an established media session."""
        return {"status": "active", "started_at": self.now, "ended_at": None}

    def ended_args(self) -> dict[str, Any]:
        """Describe a completed call with retained timestamps."""
        return self.session_args(status="ended", started_at=self.now, ended_at=self.now)

    def duplicate_args(self) -> dict[str, Any]:
        """Attempt to start a second open call in an occupied room."""
        return {"room": self.room}

    def archived_args(self) -> dict[str, Any]:
        """Attempt to create a call in an archived room."""
        self.other_room.archived = True
        self.other_room.save()
        return self.session_args()

    def add_later_session(self, session: ConferenceSession) -> None:
        """Allow a new call in the same persistent room after completion."""
        later = ConferenceSession.objects.create(room=session.room)
        self.assertNotEqual(later.livekit_room_name, session.livekit_room_name)
